head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = "ULDSTF19000_POP.xml";
//번역지원 화면 회사 추가 팝업

scwin.gLdMktTp = js_market; //세션의 시장구분
scwin.LastJob = "조회";
scwin.gRdoMktId;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    if (scwin.gLdMktTp == '1' || scwin.gLdMktTp == '2' || scwin.gLdMktTp == '4' || scwin.gLdMktTp == '6') {
        $c.stf.setObjectValue(rdo_MKT_ID, js_market);
        rdo_MKT_ID.setDisabled(true);
        //showObj(panel_mkt, false);
        //showObj(img_search,false);

    } else {
        scwin.gRdoMktId = $c.frame.path("../").scwin.gRdoMktId;
        $c.stf.setObjectValue(rdo_MKT_ID, scwin.gRdoMktId);
        rdo_MKT_ID.setDisabled(false);
        //showObj(img_search,true);

        scwin.gLdMktTp = $c.stf.getObjectValue(rdo_MKT_ID);
    }
    scwin.fn_setHeader();
};
scwin.fn_setHeader = function() {
    dts_Save.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=ENG_TRANSL_OBJ_COM_ADD_DEL";
    dts_Save.Reset();
    dts_Save.insertRow();
};
scwin.fn_Search = function() {
    $c.cm.ShowWin(grd_jongmok);
    var url = "/DsclSearchAll.do?method=listEngTranslObjCom";
    url += "&LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID);
    url += "&ISUR_CD=";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_jongmok.DataID = encodeURI(url);
    dts_jongmok.reset();
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    //gComAbbrv = dts_jongmok.NameString(eval(obj),"COM_ABBRV");
    gIsurCd = dts_jongmok.getCellData(eval(obj), "ISUR_CD");
};
scwin.fn_save = function() {
    if (txb_isur_cd.getValue().length != 5) {
        $c.win.alert("회사 코드 5자리를 입력해주세요");
        txb_isur_cd.focus();
        return;
    }
    if (txb_com_abbrv.getValue().length <= 0) {
        $c.win.alert("회사명을 입력해주세요");
        txb_com_abbrv.focus();
        return;
    }
    for (var i = 0; i < dts_jongmok.getTotalRow(); i++) {
        if (dts_jongmok.getCellData(i, "ISUR_CD") == txb_isur_cd.getValue()) {
            $c.win.alert("이미 등록된 법인입니다.");
            return;
        }

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

    }
    dts_Save.setCellData(1, "EMP_NO", js_emp_no);
    scwin.LastJob = "저장"; /*ORG SRC: dts_Save.UserStatus(1) = TB_JOB_INSERT;*/ X = TB_JOB_INSERT;
    trs_Save.Action = "/DsclSearchAll.do?method=addEngTranslObjCom" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Save)";
    trs_Save.Post();
};
scwin.fn_delete = function(row) {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    dts_Save.setCellData(1, "DEL_ISUR_CD", dts_jongmok.getCellData(row, "ISUR_CD"));
    dts_Save.setCellData(1, "LD_MKT_TP_CD", $c.stf.getObjectValue(rdo_MKT_ID));
    dts_Save.setCellData(1, "EMP_NO", js_emp_no);
    scwin.LastJob = "삭제"; /*ORG SRC: dts_Save.UserStatus(1) = TB_JOB_DELETE;*/ X = TB_JOB_DELETE;
    trs_Save.Action = "/DsclSearchAll.do?method=delEngTranslObjCom" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Save)";
    trs_Save.Post();
};
scwin.dts_jongmok_OnLoadCompleted = function(rowcount) {
    if (rowcount > 0) {
        $c.stf.showObj(panel_page, true);
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    } else {
        $c.stf.showObj(panel_page, false);
    }
    $c.cm.CloseWin(rowcount, grd_jongmok);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    //Grd_com_isur.style.display ="";
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.img_search_onclick = function() {
    scwin.fn_Search();
};
scwin.img_add_onclick = function() {
    scwin.fn_save();
};
scwin.grd_jongmok_OnClick = function(row, colid) {
    if (row == 0) return;
    if (colid == "DELETE_YN") {
        if (confirm("정말 삭제하시겠습니까?")) {
            scwin.fn_delete(row);
        }
    }
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert(scwin.LastJob + " 실패하였습니다.");
    //alert_error(trs_Save);	
    txb_com_abbrv.setValue("");
    dts_Save.Reset();
    dts_Save.insertRow(); // 성공일 때 Default로 한줄 추가해 놓는다.
    scwin.fn_Search();
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert(scwin.LastJob + " 완료되었습니다.");
    txb_com_abbrv.setValue("");
    dts_Save.Reset();
    dts_Save.insertRow(); // 성공일 때 Default로 한줄 추가해 놓는다.
    scwin.fn_Search();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.fn_Search();
};
scwin.img_com_srch_onclick = function() {
    $c.cm.ListIsurcdSearch(txb_isur_cd, txb_com_abbrv, scwin.gLdMktTp, "Y");
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_02);
    $c.data.downloadGridViewOffice(grd_jongmok, "영문번역대상법인 목록", "영문번역대상법인 목록" + ".xlsx", "8", 0);
};
